def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""
    s = sorted(set(nums))
    parts: list[str] = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j + 1 < n and s[j + 1] == s[j] + 1:
            j += 1
        run_length = j - i + 1
        if run_length >= 3:
            parts.append(f"{s[i]}..{s[j]}")
            i = j + 1
        else:
            parts.append(str(s[i]))
            i += 1
    return ",".join(parts)
