import re


_AMOUNT_RE = re.compile(r"^\s*([+-]?)\s*\$?\s*([0-9][0-9,]*(\.[0-9]+)?|\.[0-9]+)\s*$")


def _parse_amount(raw) -> float | None:
    if raw is None:
        return None
    s = str(raw).strip()
    if not s:
        return None
    match = _AMOUNT_RE.match(s)
    if not match:
        return None
    sign, digits = match.group(1), match.group(2)
    try:
        value = float(digits.replace(",", ""))
    except ValueError:
        return None
    return -value if sign == "-" else value


def top_customers(rows: list[dict], n: int) -> list[tuple[str, float]]:
    if n <= 0:
        return []

    display_names: dict[str, str] = {}
    totals: dict[str, float] = {}

    for row in rows:
        if not isinstance(row, dict):
            continue
        raw_name = row.get("customer")
        if raw_name is None:
            continue
        name = str(raw_name).strip()
        if not name:
            continue

        amount = _parse_amount(row.get("amount"))
        if amount is None:
            continue

        key = name.casefold()
        if key not in totals:
            display_names[key] = name
            totals[key] = 0.0
        totals[key] += amount

    ranked = sorted(
        ((display_names[key], round(total, 2)) for key, total in totals.items()),
        key=lambda item: (-item[1], item[0]),
    )
    return ranked[:n]
